package com.reeltracker.accessibility.statemachine

import com.reeltracker.accessibility.EventSignature
import com.reeltracker.accessibility.EventSnapshot
import com.reeltracker.domain.model.Platform

/**
 * Layer 1 gesture-window deduplicator.
 *
 * Prevents multiple accessibility callbacks generated by a single physical gesture from
 * each producing a separate transition candidate, while ensuring two genuinely separate
 * gestures are not erroneously coalesced.
 *
 * ## Deduplication key
 *
 * A five-field [EventSignature]:
 * - `eventType`, `sourceViewId`, `scrollY`, `scrollDeltaY`, `eventAction`
 *
 * An event is a within-gesture duplicate if and only if **all five fields** equal the
 * last-passed signature for the same platform AND the event arrives within
 * [deduplicationWindowMs] of that last-passed event.
 *
 * ## API-level constraint (TC-13)
 *
 * On API 26–27 `scrollDeltaY` is unavailable and stored as
 * [EventSnapshot.SCROLL_DELTA_UNAVAILABLE]. Two events with this sentinel value on both
 * sides compare as equal on that field (same unavailability), making the deduplicator
 * more conservative on those API levels.
 *
 * ## Known limitation (TC-13 — scroll position recycling)
 *
 * Vertical video feeds commonly recycle scroll positions: after swiping to the next
 * video the container's `scrollY` may reset to the same value. When this happens, two
 * genuine rapid swipes may produce identical signatures within the deduplication window
 * and the second will be blocked. This is documented behaviour, not a bug.
 *
 * Not thread-safe. Must be accessed from the accessibility service main thread.
 */
class EventSignatureDeduplicator(
    private val deduplicationWindowMs: Long = DEFAULT_WINDOW_MS,
    private val clock: () -> Long = { System.currentTimeMillis() },
) {

    companion object {
        const val DEFAULT_WINDOW_MS = 120L
    }

    /** Last signature that was allowed through per platform, with its timestamp. */
    private val lastPassed: MutableMap<Platform, Pair<EventSignature, Long>> = mutableMapOf()

    /**
     * Returns `true` if [snapshot] should proceed to the detection pipeline.
     *
     * Blocks the event when it is a within-gesture duplicate: same full [EventSignature]
     * as the last-passed event for this platform AND arrived within [deduplicationWindowMs].
     *
     * When both sides carry [EventSnapshot.SCROLL_DELTA_UNAVAILABLE], the delta field
     * is treated as equal (same unavailability). This is intentionally conservative on
     * API 26/27 — documented limitation TC-13.
     */
    fun shouldPass(platform: Platform, snapshot: EventSnapshot): Boolean {
        val sig   = snapshot.toSignature()
        val nowMs = snapshot.timestampMs
        val last  = lastPassed[platform]

        val isDuplicate = last != null &&
            last.first == sig &&
            nowMs - last.second < deduplicationWindowMs

        if (!isDuplicate) {
            lastPassed[platform] = sig to nowMs
        }
        return !isDuplicate
    }

    /** Reset state for one platform (or all platforms if [platform] is null). */
    fun reset(platform: Platform? = null) {
        if (platform != null) lastPassed.remove(platform) else lastPassed.clear()
    }
}
